const groupLogsByType = (
  rawLogs: T.BuildLog[],
  filterType: FilterState,
): FilteredLog[] => {
  const logs = rawLogs.map((l, index) => ({ ...l, index }));
  const groupedLogs = logs.reduce((groups, log) => {
    const logType = log.error ? 'errors' : log.warning ? 'warnings' : 'all';
    if (groups.length === 0 || logType !== groups[groups.length - 1].type) {
      groups.push({ type: logType, logs: [log], hidden: logType !== filterType });
    } else {
      groups[groups.length - 1].logs.push(log);
      groups[groups.length - 1].hidden = groups[groups.length - 1].hidden && log.type !== filterType;
    }
    return groups;
  }, []);

  return groupedLogs.reduce((groups, group) => {
    if (groups.length === 0 || groups[groups.length - 1].hidden === group.hidden) {
      groups[groups.length - 1] = { ...groups[groups.length - 1], logs: [...groups[groups.length - 1].logs, ...group.logs] };
    } else {
      groups.push({ hidden: group.hidden, logs: group.logs });
    }
    return groups;
  }, []);
};
```

