import { createContext, useState } from 'react';

const StudentFeedbackContext = createContext();

const StudentFeedbackProvider = ({ children }) => {
  const [feedback, setFeedback] = useState({
    overallSatisfaction: '',
    instruction: '',
    material: '',
    interaction: '',
  });

  const handleFormChange = (event) => {
    setFeedback((prevFeedback) => ({
      ...prevFeedback,
      [event.target.name]: event.target.value,
    }));
  };

  return (
    <StudentFeedbackContext.Provider value={{ feedback, handleFormChange }}>
      {children}
    </StudentFeedbackContext.Provider>
  );
};

export { StudentFeedbackProvider, StudentFeedbackContext };
```
